SELECT 이름 FROM 사원
WHERE 부서 = '영업' OR 부서 = '기획'
  AND 급여 >= 450;

SELECT * FROM 사원
WHERE 급여 BETWEEN 260 AND 340
  AND 부서 NOT IN ('총무', '기획');

UPDATE 사원 SET 급여 = 급여 + 50
WHERE 부서 = '기획';

SELECT SUM(급여) FROM 사원;

SELECT 사원.이름, 부서.위치
FROM 사원 INNER JOIN 부서
  ON 사원.부서 = 부서.부서명;

SELECT MAX(급여) - MIN(급여) AS 차이
FROM 사원
WHERE 부서 <> '기획';
